function solve({config,state,event}){
  if(state===null){
    state={seq:0,log:[],acks:{},view:{}};
    for(const r of config.readers)state.acks[r]=0;
  }
  if(event.type==='set'){
    const seq=++state.seq;
    state.log.push({seq,key:event.key,value:event.value});
    state.view[event.key]=event.value;
  }else if(event.type==='ack'){
    const old=state.acks[event.reader];
    if(old!==undefined&&old<=event.seq&&event.seq<=state.seq)
      state.acks[event.reader]=event.seq;
  }else if(event.type==='compact'){
    let watermark=Infinity;
    for(const r of config.readers)
      if(state.acks[r]<watermark)watermark=state.acks[r];
    const latest={};
    for(const rec of state.log)
      if(rec.seq<=watermark)latest[rec.key]=rec;
    const kept=[];
    for(const rec of state.log)
      if(rec.seq>watermark||latest[rec.key]===rec)kept.push(rec);
    state.log=kept;
  }
  return {state,output:{log:state.log.map(rec=>rec.seq),view:{...state.view}}};
}
